import numpy as np
lines=open('opt_nh0b.xyz').read().splitlines()
atoms=[]
for l in lines[2:]:
    p=l.split()
    atoms.append((p[0], np.array([float(p[1]),float(p[2]),float(p[3])])))
els=[a[0] for a in atoms]; xyz=[a[1] for a in atoms]
def d(i,j): return np.linalg.norm(xyz[i]-xyz[j])
# check all bond lengths for bonded pairs
cov={'H':0.37,'C':0.77,'N':0.75,'O':0.73,'Cl':1.02,'Rh':1.35}
bad=[]
bonds={'CC':[],'CH':[],'CO':[],'CN':[],'CCl':[],'NH':[],'Rh':[]}
for i in range(len(els)):
    for j in range(i+1,len(els)):
        dd=d(i,j)
        lim=(cov[els[i]]+cov[els[j]])*1.3
        if dd<lim:
            key=''.join(sorted([els[i],els[j]]))
            if els[i]=='Rh' or els[j]=='Rh': key='Rh'
            bonds.setdefault(key,[]).append(round(dd,3))
            # flag unusual
            typ=''.join(sorted([els[i],els[j]]))
            ranges={'CC':(1.2,1.6),'CH':(0.9,1.2),'CO':(1.1,1.55),'CN':(1.2,1.55),'CCl':(1.6,1.9),'HO':(0.9,1.1),'HN':(0.9,1.1)}
            if typ in ranges and not (ranges[typ][0]<=dd<=ranges[typ][1]):
                bad.append((typ,i,j,round(dd,3)))
print('bond summary:')
for k,v in bonds.items():
    print(' ',k,'n=',len(v),'min',min(v),'max',max(v))
print('unusual bonds:',bad)
# clash check (non-bonded)
worst=[]
vdw={'H':1.20,'C':1.70,'N':1.55,'O':1.52,'Cl':1.75,'Rh':1.7}
for i in range(len(els)):
    for j in range(i+1,len(els)):
        dd=d(i,j)
        lim=(cov[els[i]]+cov[els[j]])*1.3
        if dd<lim: continue
        vlim=0.7*(vdw[els[i]]+vdw[els[j]])
        if dd<vlim: worst.append((round(dd,2),els[i]+str(i),els[j]+str(j)))
worst.sort()
print('vdw clashes (<0.7 sum):', worst[:10], 'count', len(worst))
print('total atoms:', len(els), 'formula: C%d H%d Cl%d N%d O%d Rh%d'%(els.count('C'),els.count('H'),els.count('Cl'),els.count('N'),els.count('O'),els.count('Rh')))
"

