    atoms.append((p[0], np.array([float(p[1]),float(p[2]),float(p[3])])))
els=[a[0] for a in atoms]; xyz=[a[1] for a in atoms]
def d(i,j): return np.linalg.norm(xyz[i]-xyz[j])
print('Rh distances: C42 %.3f, N44 %.3f, O31 %.3f, O32 %.3f'%(d(0,42),d(0,44),d(0,31),d(0,32)))
print('Rh-Cp:', [round(d(0,k),3) for k in [1,3,5,7,9]])
cov={'H':0.37,'C':0.77,'N':0.75,'O':0.73,'Cl':1.02,'Rh':1.35}
vdw={'H':1.20,'C':1.70,'N':1.55,'O':1.52,'Cl':1.75,'Rh':1.7}
worst=[]
for i in range(len(els)):
    for j in range(i+1,len(els)):
        dd=d(i,j)
        lim=(cov[els[i]]+cov[els[j]])*1.3
        if dd<lim: continue
        vlim=0.7*(vdw[els[i]]+vdw[els[j]])
        if dd<vlim: worst.append((round(dd,2),els[i]+str(i),els[j]+str(j)))
worst.sort()
print('vdw clashes (<0.7 sum):', worst, 'count', len(worst))
# H-H check
hh=[]
for i in range(len(els)):
    if els[i]!='H': continue
    for j in range(i+1,len(els)):
        if els[j]!='H': continue
        if d(i,j)<1.8: hh.append(round(d(i,j),2))
hh.sort()
print('shortest H...H:', hh[:5])
